import { test, expect } from '@playwright/test';

test.describe('Password Confirmation Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup'); // Replace with the actual signup page URL
  });

  test('should show error message when passwords do not match', async ({ page }) => {
    await page.fill(getByLabel('Password'), 'password123');
    await page.fill(getByLabel('Confirm Password'), 'password321');
    await page.waitForTimeout(500); // Simulate real-time validation delay
    const errorMessage = await page.getByText('Passwords do not match');
    await expect(errorMessage).toBeVisible();
  });

  test('should not show error message when passwords match', async ({ page }) => {
    await page.fill(getByLabel('Password'), 'password123');
    await page.fill(getByLabel('Confirm Password'), 'password123');
    await page.waitForTimeout(500); // Simulate real-time validation delay
    const errorMessage = page.getByText('Passwords do not match');
    await expect(errorMessage).not.toBeVisible();
  });
});
